//! Tests for reading symbols and the ABI checks on ELF objects.
//!
//! The ELF objects are generated by the tests. The same imports are written
//! both with and without a static symbol table (`.symtab`), to test that
//! stripped objects are checked in the same way as unstripped objects.

use std::collections::HashMap;
use std::str::FromStr;

use kernel_abi_check::{
    check_manylinux, check_python_abi, check_torch_stable_abi, undefined_symbols,
    ManylinuxViolation, PythonAbiViolation, TorchStableAbiViolation, UndefinedSymbol, Version,
};
use object::write::elf::{FileHeader, Sym, Vernaux, Verneed, Writer};
use object::{elf, Architecture, Endianness, Object};

const LIBC: &str = "libc.so.6";

/// A symbol in the dynamic symbol table of a generated object.
struct Import {
    /// Symbol name.
    name: &'static str,

    /// The library and version that the symbol is imported with, e.g.
    /// `("libc.so.6", "GLIBC_2.14")`.
    version: Option<(&'static str, &'static str)>,

    /// Whether the symbol is defined by the object, rather than imported.
    defined: bool,
}

fn import(name: &'static str) -> Import {
    Import {
        name,
        version: None,
        defined: false,
    }
}

fn versioned(name: &'static str, file: &'static str, version: &'static str) -> Import {
    Import {
        name,
        version: Some((file, version)),
        defined: false,
    }
}

fn export(name: &'static str) -> Import {
    Import {
        name,
        version: None,
        defined: true,
    }
}

/// Write an x86_64 ELF shared object with the given dynamic symbols. If
/// `with_symtab` is set, the object also has a static symbol table with
/// versioned names (`name@VERSION`), like the object has after linking.
fn build_elf(symbols: &[Import], with_symtab: bool) -> Vec<u8> {
    // Version requirements per file, in order of first use.
    let mut needs: Vec<(&str, Vec<&str>)> = Vec::new();
    for (file, version) in symbols.iter().filter_map(|symbol| symbol.version) {
        match needs.iter_mut().find(|(f, _)| *f == file) {
            Some((_, versions)) => {
                if !versions.contains(&version) {
                    versions.push(version);
                }
            }
            None => needs.push((file, vec![version])),
        }
    }

    // Version indices start at 2, 0 and 1 are for local and global.
    let mut version_indices: HashMap<(&str, &str), u16> = HashMap::new();
    for (file, versions) in &needs {
        for version in versions {
            let index = version_indices.len() as u16 + 2;
            version_indices.insert((*file, *version), index);
        }
    }
    let vernaux_count: usize = needs.iter().map(|(_, versions)| versions.len()).sum();

    // Names in the static symbol table include the version.
    let symtab_names: Vec<String> = symbols
        .iter()
        .map(|symbol| match symbol.version {
            Some((_, version)) => format!("{}@{}", symbol.name, version),
            None => symbol.name.to_string(),
        })
        .collect();

    let mut data = Vec::new();
    let mut writer = Writer::new(Endianness::Little, true, &mut data);

    // Strings.
    let dynamic_names: Vec<_> = symbols
        .iter()
        .map(|symbol| writer.add_dynamic_string(symbol.name.as_bytes()))
        .collect();
    let need_names: Vec<_> = needs
        .iter()
        .map(|(file, versions)| {
            (
                writer.add_dynamic_string(file.as_bytes()),
                versions
                    .iter()
                    .map(|version| writer.add_dynamic_string(version.as_bytes()))
                    .collect::<Vec<_>>(),
            )
        })
        .collect();
    let static_names: Vec<_> = if with_symtab {
        symtab_names
            .iter()
            .map(|name| writer.add_string(name.as_bytes()))
            .collect()
    } else {
        Vec::new()
    };

    // Reserve section indices.
    writer.reserve_null_section_index();
    writer.reserve_dynsym_section_index();
    writer.reserve_dynstr_section_index();
    writer.reserve_gnu_versym_section_index();
    writer.reserve_gnu_verneed_section_index();
    if with_symtab {
        writer.reserve_symtab_section_index();
        writer.reserve_strtab_section_index();
    }
    writer.reserve_shstrtab_section_index();

    // Reserve symbol indices and the file ranges.
    writer.reserve_file_header();
    writer.reserve_null_dynamic_symbol_index();
    for _ in symbols {
        writer.reserve_dynamic_symbol_index();
    }
    writer.reserve_dynsym();
    writer.reserve_dynstr();
    writer.reserve_gnu_versym();
    writer.reserve_gnu_verneed(needs.len(), vernaux_count);
    if with_symtab {
        writer.reserve_null_symbol_index();
        for _ in symbols {
            writer.reserve_symbol_index(None);
        }
        writer.reserve_symtab();
        writer.reserve_strtab();
    }
    writer.reserve_shstrtab();
    writer.reserve_section_headers();

    // Write everything in the same order.
    writer
        .write_file_header(&FileHeader {
            os_abi: elf::ELFOSABI_NONE,
            abi_version: 0,
            e_type: elf::ET_DYN,
            e_machine: elf::EM_X86_64,
            e_entry: 0,
            e_flags: 0,
        })
        .unwrap();

    let symbol_entry = |name, defined: bool| Sym {
        name: Some(name),
        section: None,
        st_info: (elf::STB_GLOBAL << 4) | elf::STT_NOTYPE,
        st_other: 0,
        // Any non-zero section index is a defined symbol.
        st_shndx: defined as u16,
        st_value: 0,
        st_size: 0,
    };

    writer.write_null_dynamic_symbol();
    for (symbol, name) in symbols.iter().zip(&dynamic_names) {
        writer.write_dynamic_symbol(&symbol_entry(*name, symbol.defined));
    }
    writer.write_dynstr();

    writer.write_null_gnu_versym();
    for symbol in symbols {
        let index = match symbol.version {
            Some(version) => version_indices[&version],
            // Global.
            None => 1,
        };
        writer.write_gnu_versym(index);
    }

    writer.write_align_gnu_verneed();
    for ((file, versions), (file_name, version_names)) in needs.iter().zip(&need_names) {
        writer.write_gnu_verneed(&Verneed {
            version: 1,
            aux_count: versions.len() as u16,
            file: *file_name,
        });
        for (version, version_name) in versions.iter().zip(version_names) {
            writer.write_gnu_vernaux(&Vernaux {
                flags: 0,
                index: version_indices[&(*file, *version)],
                name: *version_name,
            });
        }
    }

    if with_symtab {
        writer.write_null_symbol();
        for (symbol, name) in symbols.iter().zip(&static_names) {
            writer.write_symbol(&symbol_entry(*name, symbol.defined));
        }
        writer.write_strtab();
    }

    writer.write_shstrtab();

    writer.write_null_section_header();
    writer.write_dynsym_section_header(0, 1);
    writer.write_dynstr_section_header(0);
    writer.write_gnu_versym_section_header(0);
    writer.write_gnu_verneed_section_header(0);
    if with_symtab {
        writer.write_symtab_section_header(1);
        writer.write_strtab_section_header();
    }
    writer.write_shstrtab_section_header();

    data
}

/// Read the undefined symbols of an object.
fn symbols_of(data: &[u8]) -> Vec<UndefinedSymbol> {
    let file = object::File::parse(data).unwrap();
    undefined_symbols(&file, data).unwrap()
}

/// Generate an object, once stripped of the static symbol table and once not
/// stripped. Check that the two really differ in the way that we expect, so
/// that the tests do not pass vacuously.
fn stripped_and_unstripped(symbols: &[Import]) -> (Vec<u8>, Vec<u8>) {
    let stripped = build_elf(symbols, false);
    let unstripped = build_elf(symbols, true);

    let stripped_file = object::File::parse(&*stripped).unwrap();
    assert_eq!(stripped_file.symbols().count(), 0);
    assert!(stripped_file.dynamic_symbols().count() > 0);

    let unstripped_file = object::File::parse(&*unstripped).unwrap();
    assert!(unstripped_file.symbols().count() > 0);

    (stripped, unstripped)
}

fn version(version: &str) -> Version {
    Version::from_str(version).unwrap()
}

fn python_symbols() -> Vec<Import> {
    vec![
        export("PyInit_example"),
        import("PyLong_FromLong"),
        // Added to the stable ABI in 3.10.
        import("PyUnicode_AsUTF8AndSize"),
        // Added to the stable ABI in 3.7.
        import("PySlice_Unpack"),
        versioned("memcpy", LIBC, "GLIBC_2.14"),
    ]
}

#[test]
fn undefined_symbols_with_versions() {
    let (stripped, unstripped) = stripped_and_unstripped(&python_symbols());

    let expected: Vec<_> = [
        ("PyLong_FromLong", None),
        ("PyUnicode_AsUTF8AndSize", None),
        ("PySlice_Unpack", None),
        ("memcpy", Some("GLIBC_2.14")),
    ]
    .into_iter()
    .map(|(name, version)| UndefinedSymbol {
        name: name.to_string(),
        version: version.map(str::to_string),
    })
    .collect();

    // Defined symbols (`PyInit_example`) are not included.
    assert_eq!(symbols_of(&stripped), expected);
    assert_eq!(symbols_of(&unstripped), expected);
}

#[test]
fn multiple_version_requirements() {
    let symbols = vec![
        versioned("memcpy", LIBC, "GLIBC_2.14"),
        versioned("printf", LIBC, "GLIBC_2.2.5"),
        versioned(
            "_ZNSt6thread6_StateD2Ev",
            "libstdc++.so.6",
            "GLIBCXX_3.4.22",
        ),
        versioned("cudaMalloc", "libcudart.so.12", "libcudart.so.12"),
        import("unversioned"),
    ];
    let (stripped, unstripped) = stripped_and_unstripped(&symbols);

    let expected: Vec<_> = [
        ("memcpy", Some("GLIBC_2.14")),
        ("printf", Some("GLIBC_2.2.5")),
        ("_ZNSt6thread6_StateD2Ev", Some("GLIBCXX_3.4.22")),
        ("cudaMalloc", Some("libcudart.so.12")),
        ("unversioned", None),
    ]
    .into_iter()
    .map(|(name, version)| UndefinedSymbol {
        name: name.to_string(),
        version: version.map(str::to_string),
    })
    .collect();

    assert_eq!(symbols_of(&stripped), expected);
    assert_eq!(symbols_of(&unstripped), expected);
}

#[test]
fn python_abi_stripped_and_unstripped() {
    let (stripped, unstripped) = stripped_and_unstripped(&python_symbols());

    for data in [&stripped, &unstripped] {
        let symbols = symbols_of(data);

        // Below the 3.10 floor, the symbols that were added later are reported.
        assert_eq!(
            check_python_abi(&version("3.9"), &symbols),
            [PythonAbiViolation::IncompatibleAbi3Symbol {
                name: "PyUnicode_AsUTF8AndSize".to_string(),
                added: version("3.10"),
            },]
            .into_iter()
            .collect()
        );
        // Everything is in the stable ABI for 3.7, except for the symbol of 3.10.
        assert_eq!(check_python_abi(&version("3.7"), &symbols).len(), 1);
        // And lower floors also report symbols that were added in between
        // (`PySlice_Unpack` in 3.7).
        assert_eq!(check_python_abi(&version("3.2"), &symbols).len(), 2);

        assert!(check_python_abi(&version("3.10"), &symbols).is_empty());
        assert!(check_python_abi(&version("3.12"), &symbols).is_empty());
    }
}

#[test]
fn python_non_abi3_symbols() {
    let (stripped, unstripped) =
        stripped_and_unstripped(&[import("PyLong_FromLong"), import("_PyUnicode_Ready")]);

    for data in [&stripped, &unstripped] {
        assert_eq!(
            check_python_abi(&version("3.12"), &symbols_of(data)),
            [PythonAbiViolation::NonAbi3Symbol {
                name: "_PyUnicode_Ready".to_string()
            }]
            .into_iter()
            .collect()
        );
    }
}

#[test]
fn manylinux_stripped_and_unstripped() {
    let (stripped, unstripped) = stripped_and_unstripped(&[
        versioned("memcpy", LIBC, "GLIBC_2.14"),
        versioned("printf", LIBC, "GLIBC_2.2.5"),
        // `pthread_cond_clockwait` was added in glibc 2.30 (2.34 after moving
        // it to libc).
        versioned("pthread_cond_clockwait", LIBC, "GLIBC_2.34"),
        // Not a glibc/libstdc++/... symbol version, ignored.
        versioned("cudaMalloc", "libcudart.so.12", "libcudart.so.12"),
    ]);

    for data in [&stripped, &unstripped] {
        let symbols = symbols_of(data);

        let violations = check_manylinux(
            "manylinux_2_28",
            Architecture::X86_64,
            Endianness::Little,
            &symbols,
        )
        .unwrap();
        assert_eq!(
            violations,
            [ManylinuxViolation::Symbol {
                name: "pthread_cond_clockwait".to_string(),
                dep: "GLIBC".to_string(),
                version: "2.34".to_string(),
            }]
            .into_iter()
            .collect()
        );

        // Everything is allowed by a newer manylinux version.
        let violations = check_manylinux(
            "manylinux_2_34",
            Architecture::X86_64,
            Endianness::Little,
            &symbols,
        )
        .unwrap();
        assert!(violations.is_empty(), "{violations:?}");
    }
}

#[test]
fn manylinux_compatible() {
    let (stripped, unstripped) = stripped_and_unstripped(&[
        versioned("memcpy", LIBC, "GLIBC_2.14"),
        versioned("printf", LIBC, "GLIBC_2.2.5"),
    ]);

    for data in [&stripped, &unstripped] {
        let violations = check_manylinux(
            "manylinux_2_28",
            Architecture::X86_64,
            Endianness::Little,
            &symbols_of(data),
        )
        .unwrap();
        assert!(violations.is_empty(), "{violations:?}");
    }
}

#[test]
fn torch_stable_abi_stripped_and_unstripped() {
    let (stripped, unstripped) = stripped_and_unstripped(&[
        // `torch::stable::` symbols are stable.
        import("_ZN5torch6stable6detail4goodEv"),
        // `c10::` is not.
        import("_ZN3c1013SomethingFailEv"),
        // Unrelated C symbol.
        import("malloc"),
    ]);

    for data in [&stripped, &unstripped] {
        let violations = check_torch_stable_abi(&version("2.9"), &symbols_of(data)).unwrap();
        assert_eq!(
            violations,
            [TorchStableAbiViolation::NonStableAbiSymbol {
                name: "c10::SomethingFail()".to_string()
            }]
            .into_iter()
            .collect()
        );
    }
}
